async function t(a,r={}){const e=await fetch(a,{cache:"no-store",...r}),i=await e.text();let n;try{n=i?JSON.parse(i):{}}catch{throw new Error(`API returned invalid JSON (${e.status})`)}if(!e.ok)throw new Error(n.error||e.statusText);return n}async function s(){const a=await t("/api/map");if(!Array.isArray(a.origin)||!a.width||!a.height||!a.resolution)throw new Error("Map metadata unavailable");return a}const o=()=>t("/api/bounds");async function c(){const a=await t("/api/tasks/delivery");if(!Array.isArray(a.vehicles)||!Array.isArray(a.stations)||typeof a.online!="boolean")throw new Error("Delivery fleet unavailable");return a}async function l(){const a=await t("/api/health");if(!a.ok||!a.services||!Array.isArray(a.vehicles))throw new Error("System health unavailable");return a}async function y(a){const r=await t("/api/simulation/faults",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(a)});if(!r.simulation_only||!Array.isArray(r.active))throw new Error("Simulation fault control unavailable");return r}async function u(a){const r=await t(`/api/state?${new URLSearchParams(a)}`);if(!Array.isArray(r.latest)||!Array.isArray(r.density))throw new Error("Traffic history unavailable");return r}async function h(a,r,e){const i=await t(`/api/track?${new URLSearchParams({vehicle_id:a,start:r,end:e})}`);if(i.vehicle_id!==a||!Array.isArray(i.points))throw new Error("Selected vehicle route unavailable");return i}export{u as a,s as b,c,o as d,h as e,l as g,y as s};
